    public static function findById(string $id): ?array
    {
        $all = static::getAllGuidelines();
        foreach ($all as $spec => $items) {
            if (isset($items[$id])) return $items[$id];
        }
        return null;
    }

    public static function getCountBySpecialty(string $specialtySlug): int
    {
        $all = static::getAllGuidelines();
        return isset($all[$specialtySlug]) ? count($all[$specialtySlug]) : 0;
    }

    public static function getTotalGuidelinesCount(): int
    {
        $total = 0;
        foreach (static::getAllGuidelines() as $items) {
            $total += count($items);
        }
        return $total;
    }
}